// ===== getAnalysis 分析获取函数 =====
function getAnalysis(type, dim, score) {
    // score: 0-100 (百分比)
    // 确定类型组
    const typeGroups = {
        'INTJ':'NT','INTP':'NT','ENTJ':'NT','ENTP':'NT',
        'INFJ':'NF','INFP':'NF','ENFJ':'NF','ENFP':'NF',
        'ISTJ':'SJ','ISFJ':'SJ','ESTJ':'SJ','ESFJ':'SJ',
        'ISTP':'SP','ISFP':'SP','ESTP':'SP','ESFP':'SP'
    };
    const group = typeGroups[type] || 'NT';
    
    // 确定倾向 (score >= 50 表示第一个倾向更强)
    let lean;
    if (dim === 'ei') lean = score >= 50 ? 'I' : 'E';
    else if (dim === 'sn') lean = score >= 50 ? 'S' : 'N';
    else if (dim === 'tf') lean = score >= 50 ? 'T' : 'F';
    else lean = score >= 50 ? 'J' : 'P';
    
    // 确定段位 0-5 (对应弱→极强)
    let seg;
    if (score < 60) seg = 0;
    else if (score < 67) seg = 1;
    else if (score < 73) seg = 2;
    else if (score < 80) seg = 3;
    else if (score < 87) seg = 4;
    else seg = 5;
    
    // 特殊：如果分数接近中点，使用中间段位
    if (score >= 47 && score <= 53) seg = 2; // 中性区域
    
    const data = ANALYSIS_DATA[group];
    if (!data) return "";
    const dimData = data[dim];
    if (!dimData) return "";
    const leanData = dimData[lean];
    if (!leanData) return "";
    return leanData[String(seg)] || leanData[2] || "";
}

